<script setup lang="ts">
definePageMeta({ layout: "workspace" });
type OrderItem = { _id: string; orderNumber: string; title: string; status: string; scheduledDate?: string; companyId?: { name?: string }; serviceId?: { name?: string } };
const { t } = useLocale();
const { data, pending, error } = await useFetch<{ items: OrderItem[] }>("/api/customer/orders");
const items = computed(() => data.value?.items || []);
</script>
<template><section class="grid gap-4 pb-8"><div><p class="text-xs font-black uppercase tracking-[0.18em] text-[var(--drixal-blue)]">{{ t("customerPortal.ordersEyebrow") }}</p><h1 class="mt-2 text-2xl font-semibold">{{ t("customerPortal.ordersTitle") }}</h1><p class="drixal-muted mt-2 text-sm">{{ t("customerPortal.ordersDescription") }}</p></div><p v-if="error" class="drixal-danger rounded-xl p-4 font-semibold">{{ error.message }}</p><p v-else-if="pending" class="drixal-panel rounded-xl p-6 text-center drixal-muted">{{ t("common.loading") }}</p><div v-else-if="items.length" class="table-scroll"><table class="business-table"><thead><tr><th>{{ t("common.order") }}</th><th>{{ t("common.provider") }}</th><th>{{ t("common.service") }}</th><th>{{ t("common.status") }}</th><th>{{ t("common.scheduledDate") }}</th></tr></thead><tbody><tr v-for="item in items" :key="item._id"><td><NuxtLink :to="`/customer/orders/${item._id}`" class="font-bold text-[var(--drixal-blue)] hover:underline">{{ item.orderNumber }}</NuxtLink><div class="drixal-muted mt-1 text-xs">{{ item.title }}</div></td><td>{{ item.companyId?.name || '-' }}</td><td>{{ item.serviceId?.name || '-' }}</td><td><UBadge :label="t(`statuses.${item.status}`)" variant="soft" /></td><td>{{ item.scheduledDate ? new Date(item.scheduledDate).toLocaleDateString() : '-' }}</td></tr></tbody></table></div><div v-else class="drixal-panel rounded-xl border-dashed p-6 text-center"><h2 class="text-lg font-semibold">{{ t("customerPortal.noOrders") }}</h2><p class="drixal-muted mt-2">{{ t("customerPortal.noOrdersDescription") }}</p></div></section></template>
